import {latestProject,normalize} from './matcher.js';
export function parseTerminal(raw,projects){const q=normalize(raw);if(/[;|&`$<>\n\r]/.test(raw))return{lines:['ACCESS DENIED — Private development environment.']};if(q==='coffee')return{lines:['ERROR: Developer caffeine levels already exceed recommended limits.']};if(q==='sudo hire alain')return{lines:['Permission granted. Excellent decision. Opening contact protocol…'],action:'contact'};const [cmd,...args]=raw.trim().toLowerCase().split(/\s+/);const list=ps=>ps.map((p,i)=>`${i+1}. ${p.name} [${p.slug}] — ${p.status}`);switch(cmd){case 'help':return{lines:['help · projects · apps · about · skills · latest','open <slug> · contact · random · clear · exit','Try coffee or sudo hire alain.']};case 'projects':return{lines:list(projects)};case 'apps':return{lines:list(projects.filter(p=>p.categories.includes('Apps')))};case 'about':return{lines:['DevMania — turning ideas into digital experiences.','Alain builds websites, applications and digital platforms.']};case 'skills':return{lines:[...new Set(projects.flatMap(p=>p.capabilities))].sort()};case 'latest':{const p=latestProject(projects);return p?{lines:[p.name],project:p}:{lines:['Launch dates have not been recorded. Use projects to explore all builds.']}}case 'open':{const slug=args.join(' ');const p=projects.find(p=>p.slug===slug||normalize(p.name)===normalize(slug));return p?{lines:['Opening '+p.name],project:p}:{lines:['Unknown project. Try one of these:',...list(projects.filter(p=>normalize(p.name).includes(normalize(slug))).slice(0,4)),...(projects.some(p=>normalize(p.name).includes(normalize(slug)))?[]:projects.slice(0,3).map(p=>p.slug))]}}case 'contact':return{lines:['Opening project enquiry…'],action:'contact'};case 'random':return{lines:['Opening a random project…'],project:projects[Math.floor(Math.random()*projects.length)]};case 'clear':return{action:'clear',lines:[]};case 'exit':return{action:'exit',lines:[]};default:return{lines:['ACCESS DENIED — Private development environment.']}}}
export function mountTerminal({dialog,content},{projects,contact,focusProject,track,el}){content.replaceChildren();const output=el('div',undefined,'terminal-output');output.setAttribute('role','log');output.setAttribute('aria-live','polite');output.append(el('p','DEV//MANIA terminal. Type help to begin.'));const form=el('form',undefined,'terminal-form');const label=el('label','devmania@portfolio:~$');const input=el('input');input.autocomplete='off';input.spellcheck=false;input.maxLength=200;input.setAttribute('aria-label','Terminal command');const submit=el('button','Run');label.append(input);form.append(label,submit);content.append(output,form);input.focus();form.onsubmit=e=>{e.preventDefault();const raw=input.value;input.value='';if(!raw.trim())return;output.append(el('p','devmania@portfolio:~$ '+raw));const result=parseTerminal(raw,projects);const command=raw.trim().split(' ')[0];track('terminal_command_used',{command:['help','projects','apps','about','skills','latest','open','contact','random','clear','exit','coffee'].includes(command)?command:'other'});if(result.action==='clear')output.replaceChildren();result.lines.forEach(line=>output.append(el('p',line)));while(output.children.length>120)output.firstChild.remove();output.scrollTop=output.scrollHeight;if(result.action==='exit')dialog.close();if(result.action==='contact')contact();if(result.project)focusProject(result.project)}}
